-- Seed: Santa Cruz do Sul e Uruguaiana (levantamentos de 20–21/10/2026). Rode DEPOIS de schema.sql.
-- Pode ser rodado de novo sem duplicar: usa ON CONFLICT para atualizar os dados cadastrais e preserva status, responsável e notas.
begin;
on conflict (id) do update set nome=excluded.nome, uf=excluded.uf, populacao=excluded.populacao, prefeito=excluded.prefeito, vice=excluded.vice, presidente_camara=excluded.presidente_camara, cadeiras_camara=excluded.cadeiras_camara, ordem=excluded.ordem, resumo=excluded.resumo;
on conflict (id) do update set cidade_id=excluded.cidade_id, grupo=excluded.grupo, orgao=excluded.orgao, cargo=excluded.cargo, nome=excluded.nome, partido=excluded.partido, telefone=excluded.telefone, whatsapp=excluded.whatsapp, email=excluded.email, endereco=excluded.endereco, rede_social=excluded.rede_social, obs_fonte=excluded.obs_fonte, foto=excluded.foto, ordem=excluded.ordem, prioritario=excluded.prioritario, vinculado_a=excluded.vinculado_a;
commit;
